1	import Foundation
2	
3	/// Switch by Speaker's planner (road map "creator-jobs" SW2a, spec §11
4	/// SW-20…SW-25): which microphone is active on a 10 ms grid, the shots those
5	/// turns make on the angle tracks, and every refusal named at once. Nothing
6	/// here is visible yet; SW2b's sheet and tool write the shots onto a Program
7	/// track.
8	///
9	/// Pure (SW-25): `defaults`, `plan`, `labels` and `shots` read no document,
10	/// file or clock. `read` (`SpeakerSwitch+Read.swift`) is the one reader, and
11	/// the series it builds are `ClipLevelSeries`'. Names no `rc_*` but
12	/// `ReelTime.snapToFrame` and `ReelTime.format`.
13	enum SpeakerSwitch {
14	    static let actionName = "Switch by Speaker"
15	    static let maxAngles = 9
16	
17	    /// What a qualifying crosstalk turn does: show the wide, or hold.
18	    enum Crosstalk: String { case wide, hold }
19	
20	    /// Seconds and dB; the defaults are SW-S4's (SW-21) and SW-22's drafts.
21	    struct Settings: Equatable {
22	        var minShot = 2.0, minTurn = 1.0, lead = 0.2, crosstalkMin = 1.0, bridge = 0.5
23	        var crosstalk: Crosstalk = .wide
24	        var bleedDB = 15.0, dominanceDB = 8.0, floorMarginDB = 6.0, voiceThreshold: Float = 0.5
25	        /// nil = off.
26	        var wideAfter: Double? = nil
27	        /// The faces mode's label (SW-81): the top angle's activity over the next's, and the
28	        /// floor it must exceed.
29	        var faceRatio = FaceActivity.ratio, faceFloor = FaceActivity.floor
30	    }
31	
32	    /// Who says who is talking (SW-83): each microphone its own person, or one microphone shared
33	    /// by two or more angles and their faces (`SpeakerSwitch+Faces.swift`).
34	    enum Mode: String { case microphones, faces }
35	
36	    /// One face-speaker angle's mouth activity on the range's grid (SW-81): step k's activity,
37	    /// nil where none can be read. Empty: not read.
38	    struct FaceAngle: Equatable {
39	        let track: UInt32
40	        let activity: [Double?]
41	    }
42	
43	    /// A person: their microphone track and the angle track that shows them.
44	    struct Speaker: Equatable { let mic: UInt32?; let angle: UInt32? }
45	    struct Pairing: Equatable { let speakers: [Speaker]; let wide: UInt32? }
46	    struct Span: Equatable { let clip: UInt32; let start: Ticks; let end: Ticks }
47	    /// An angle track and its picture clips (`SwitchAngle.pictureClips`), by start.
48	    struct AngleTrack: Equatable { let track: UInt32; let clips: [Span] }
49	
50	    /// One microphone track on the range's grid: step k is
51	    /// `[from + k·step, from + (k+1)·step)`. Empty arrays: not read.
52	    struct Microphone: Equatable {
53	        let track: UInt32
54	        /// ℓ(k) in dB over the centred window; −∞ when silent.
55	        let level: [Double]
56	        /// v(k).
57	        let voice: [Float]
58	        /// A selected clip of this track plays at the step's midpoint.
59	        let covered: [Bool]
60	    }
61	
62	    struct Input {
63	        let from: Ticks, to: Ticks, fps: Fps
64	        /// Front first.
65	        let angles: [AngleTrack]
66	        /// Front first.
67	        let microphones: [Microphone]
68	        let pairing: Pairing
69	        /// `read`'s: still analysed, no speech detection.
70	        let problems: [String]
71	        /// `ShotSplit.clipCount` of the document's project.
72	        let clipCount: Int
73	        let settings: Settings
74	        /// The faces mode's angles, front first (`readFaces`); empty in the microphones mode.
75	        var faces: [FaceAngle] = []
76	    }
77	
78	    /// A step's label; `person` names the microphone track (in the faces mode, the angle's).
79	    enum Label: Equatable { case person(UInt32), crosstalk, nobody }
80	    struct Shot: Equatable { let angle: UInt32; let start: Ticks; let end: Ticks }
81	    enum Plan: Equatable { case refused([String]); case planned(shots: [Shot], added: Int) }
82	
83	    // MARK: - SW-20's defaults
84	
85	    /// The angles, microphones and pairing a selection implies, front first.
86	    static func defaults(selection: [ClipSnapshot], in snapshot: ProjectSnapshot)
87	        -> (angles: [UInt32], microphones: [UInt32], pairing: Pairing)
88	    {
89	        let front = snapshot.tracks.reversed().map(\.id)
90	        func holds(_ track: UInt32, _ test: (ClipSnapshot) -> Bool) -> Bool {
91	            selection.contains { $0.track == track && test($0) }
92	        }
93	        let angles = front.filter { holds($0) { isPicture($0, in: snapshot) } }
94	        let files = front.filter {
95	            holds($0) { playsSound($0, in: snapshot) && snapshot.media(for: $0)?.hasVideo == false }
96	        }
97	        let microphones = files.isEmpty
98	            ? angles.filter { holds($0) { playsSound($0, in: snapshot) } } : files
99	
100	        var speakers: [Speaker] = []
101	        var used: Set<UInt32> = []
102	        for mic in microphones where angles.contains(mic) {
103	            used.insert(mic)
104	        }
105	        var free = angles.filter { !used.contains($0) }.makeIterator()
106	        for mic in microphones {
107	            if angles.contains(mic) {
108	                speakers.append(Speaker(mic: mic, angle: mic))
109	            } else if let angle = free.next() {
110	                used.insert(angle)
111	                speakers.append(Speaker(mic: mic, angle: angle))
112	            } else {
113	                speakers.append(Speaker(mic: mic, angle: nil))
114	            }
115	        }
116	        let left = angles.filter { !used.contains($0) }
117	        // SW-83: one microphone shared by every angle, and no wide (the faces mode).
118	        if microphones.count == 1, angles.count >= 2, let mic = microphones.first {
119	            return (angles, microphones,
120	                    Pairing(speakers: angles.map { Speaker(mic: mic, angle: $0) }, wide: nil))
121	        }
122	        return (angles, microphones,
123	                Pairing(speakers: speakers, wide: left.count == 1 ? left.first : nil))
124	    }
125	
126	    /// A `detach_audio` half: the sound of a file with pictures.
127	    static func isDetachedSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
128	        !clip.enabled.video && clip.linked != nil && snapshot.media(for: clip)?.hasVideo == true
129	    }
130	
131	    /// A media clip with a picture that may make its track an angle.
132	    static func isPicture(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
133	        guard case .media = clip.source, snapshot.sourceSize(of: clip) != nil else { return false }
134	        return !(clip.enabled.video == false && clip.linked != nil)
135	    }
136	
137	    /// A media clip that sounds, by the snapshot alone (no plan here): its
138	    /// media has audio, its sound is on, and it is no detached camera sound.
139	    static func playsSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
140	        guard case .media = clip.source, clip.enabled.audio,
141	            snapshot.media(for: clip)?.hasAudio == true
142	        else { return false }
143	        return !isDetachedSound(clip, in: snapshot)
144	    }
145	
146	    // MARK: - The plan
147	
148	    static func plan(_ input: Input) -> Plan {
149	        let refusals = refusals(input)
150	        if !refusals.isEmpty { return .refused(refusals) }
151	        let step = stepTicks
152	        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
153	        let faces = mode(input.pairing) == .faces
154	        let all = faces
155	            ? faceLabels(input)
156	            : labels(input.microphones.filter { $0.level.count == count }, settings: input.settings)
157	        let planned = shots(
158	            labels: all, from: input.from, to: input.to, fps: input.fps,
159	            pairing: faces ? facePairing(input.pairing) : input.pairing,
160	            angles: input.angles, settings: input.settings)
161	        let added = clipsAdded(planned, angles: input.angles, from: input.from, to: input.to)
162	        let most = Int(RC_MAX_CLIPS)
163	        if input.clipCount + added > most {
164	            return .refused([
165	                "Switch by Speaker would add \(added) clips to \(input.clipCount); the most is "
166	                    + "\(most) — raise the minimum shot."
167	            ])
168	        }
169	        return .planned(shots: planned, added: added)
170	    }
171	
172	    /// SW-24's list, in its order; empty when nothing is refused.
173	    static func refusals(_ input: Input) -> [String] {
174	        var out: [String] = []
175	        let angles = input.angles.map(\.track)
176	        if angles.count < 2 {
177	            out.append(
178	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
179	                    + "with a picture.")
180	        }
181	        if angles.count > maxAngles {
182	            out.append(
183	                "Switch by Speaker takes at most nine angles; \(angles.count) tracks hold a "
184	                    + "selected clip with a picture.")
185	        }
186	        let microphones = input.microphones.map(\.track)
187	        let faces = mode(input.pairing) == .faces
188	        // SW-83: in the faces mode a speaker on the wide takes no part.
189	        for speaker in input.pairing.speakers
190	        where !(faces && speaker.angle != nil && speaker.angle == input.pairing.wide) {
191	            guard let mic = speaker.mic, microphones.contains(mic) else {
192	                let track = speaker.angle ?? speaker.mic ?? 0
193	                out.append("The speaker on track \(track) has no microphone.")
194	                continue
195	            }
196	            if speaker.angle.map({ !angles.contains($0) }) ?? true {
197	                out.append("The microphone on track \(mic) has no angle to show its speaker.")
198	            }
199	        }
200	        var counted: [UInt32] = []
201	        for mic in input.pairing.speakers.compactMap(\.mic) where !faces && !counted.contains(mic) {
202	            counted.append(mic)
203	            let n = input.pairing.speakers.filter { $0.mic == mic }.count
204	            if n > 1 {
205	                out.append(
206	                    "Track \(mic) is the microphone for \(n) speakers; each person needs their "
207	                        + "own microphone.")
208	            }
209	        }
210	        out += input.problems
211	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
212	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
213	        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
214	        out += silentMicrophones(input)
215	        // SW-84: a read angle with no step whose mouth can be read.
216	        for angle in input.faces where angle.activity.count == count
217	            && !angle.activity.contains(where: { $0 != nil })
218	        {
219	            out.append(
220	                "The camera on track \(angle.track) shows no face whose mouth can be read between "
221	                    + "\(a) and \(b), so it never says who is talking.")
222	        }
223	        if let gap = firstGap(input.angles, from: input.from, to: input.to) {
224	            out.append(
225	                "No angle has a picture between "
226	                    + "\(ReelTime.format(gap.from, fps: input.fps, frames: true)) and "
227	                    + "\(ReelTime.format(gap.to, fps: input.fps, frames: true)).")
228	        }
229	        return out
230	    }
231	
232	    /// SW-24's no-speech sentences: each read microphone with no speech step inside the range.
233	    static func silentMicrophones(_ input: Input) -> [String] {
234	        var out: [String] = []
235	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
236	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
237	        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
238	        for mic in input.microphones where mic.voice.count == count {
239	            let speaks = mic.voice.indices.contains {
240	                mic.covered[$0] && mic.voice[$0] >= input.settings.voiceThreshold
241	            }
242	            if !speaks {
243	                out.append(
244	                    "The microphone on track \(mic.track) has no speech between \(a) and \(b), "
245	                        + "so it never says who is talking.")
246	            }
247	        }
248	        return out
249	    }
250	
251	    /// The first stretch of `[from, to)` no angle covers.
252	    static func firstGap(_ angles: [AngleTrack], from: Ticks, to: Ticks)
253	        -> (from: Ticks, to: Ticks)?
254	    {
255	        var t = from
256	        while t < to {
257	            if let end = angles.compactMap({ reach($0, from: t) }).max() {
258	                t = end
259	                continue
260	            }
261	            let next = angles.flatMap(\.clips).map(\.start).filter { $0 > t }.min() ?? to
262	            return (t, min(next, to))
263	        }
264	        return nil
265	    }
266	
267	    /// How far `angle`'s clips cover contiguously from `t`; nil when they
268	    /// do not cover `t` (SW-13's rule).
269	    static func reach(_ angle: AngleTrack, from t: Ticks) -> Ticks? {
270	        var reached = angle.clips.filter { $0.start <= t && $0.end > t }.map(\.end).max()
271	        // A clip starting at or before the edge extends it (abutting files
272	        // cover their join): loop until the edge no longer moves.
273	        while let end = reached {
274	            let further = angle.clips.filter { $0.start <= end && $0.end > end }.map(\.end).max()
275	            guard let further else { break }
276	            reached = further
277	        }
278	        return reached
279	    }
280	
281	    /// SW-24's N: per shot, the angle clips it overlaps (the later one
282	    /// taking over where two overlap, SW-15 (d)), plus a split for each
283	    /// angle clip straddling `from` and each straddling `to`.
284	    static func clipsAdded(_ shots: [Shot], angles: [AngleTrack], from: Ticks, to: Ticks) -> Int {
285	        var n = 0
286	        for shot in shots {
287	            guard let angle = angles.first(where: { $0.track == shot.angle }) else { continue }
288	            let crossing = angle.clips.filter { $0.end > shot.start && $0.start < shot.end }
289	            for (index, clip) in crossing.enumerated() {
290	                let next = index + 1 < crossing.count ? crossing[index + 1].start : shot.end
291	                if min(clip.end, next, shot.end) > max(clip.start, shot.start) { n += 1 }
292	            }
293	        }
294	        for clip in angles.flatMap(\.clips) {
295	            if clip.start < from && from < clip.end { n += 1 }
296	            if clip.start < to && to < clip.end { n += 1 }
297	        }
298	        return n
299	    }
300	}
