57	extension SpeakerSwitch {
58	    /// "N shots: k on <name>, …. Adds M clips." — the angles in the order they first show,
59	    /// each named by `names` (a track id when it has none).
60	    static func summary(_ shots: [Shot], added: Int, names: [UInt32: String]) -> String {
61	        var order: [UInt32] = []
62	        var counts: [UInt32: Int] = [:]
63	        for shot in shots {
64	            if counts[shot.angle] == nil { order.append(shot.angle) }
65	            counts[shot.angle, default: 0] += 1
66	        }
67	        let each = order.map { "\(counts[$0] ?? 0) on \(names[$0] ?? "track \($0)")" }
68	        let count = shots.count == 1 ? "1 shot" : "\(shots.count) shots"
69	        let adds = added == 1 ? "1 clip" : "\(added) clips"
70	        return "\(count): \(each.joined(separator: ", ")). Adds \(adds)."
71	    }
72	
73	    /// The name each of `tracks` is listed by: its own, with " (n)" — n its 1-based position
74	    /// from the back — when two of them share it (SW-13's rule, `SwitchAngle.angles`).
75	    static func titles(_ tracks: [UInt32], in snapshot: ProjectSnapshot) -> [UInt32: String] {
76	        let names = tracks.map { snapshot.track($0)?.name ?? "Track" }
77	        var out: [UInt32: String] = [:]
78	        for (track, name) in zip(tracks, names) {
79	            if names.filter({ $0 == name }).count > 1 {
80	                out[track] = "\(name) (\((snapshot.trackIndex(of: track) ?? 0) + 1))"
81	            } else {
82	                out[track] = name
83	            }
84	        }
85	        return out
86	    }
87	
88	    /// The sheet's Microphone choices, front first: every track holding a selected `.media`
89	    /// clip with its sound on and a media with audio, a detached camera sound included (SW-20).
90	    static func microphoneChoices(_ selection: [ClipSnapshot], in snapshot: ProjectSnapshot)
91	        -> [UInt32]
92	    {
93	        snapshot.tracks.reversed().map(\.id).filter { track in
94	            selection.contains { clip in
95	                guard clip.track == track, case .media = clip.source, clip.enabled.audio else {
96	                    return false
97	                }
98	                return snapshot.media(for: clip)?.hasAudio == true
99	            }
100	        }
101	    }
102	}
