3	/// Switch by Speaker's faces mode (road map "creator-jobs" SW8, spec §11 SW-80…SW-86): one
4	/// microphone shared by two or more angles, who talks decided by each angle's mouth activity
5	/// (`FaceActivity`) while the microphone hears speech, and SW-22's `shots` run unchanged over
6	/// those labels with the face pairing.
7	///
8	/// `withoutWide`, `faceSpeakers`, `mode`, `facePairing`, `faceLabels` and `faceSeries` are pure
9	/// (SW-25). `readFaces` (from `read`) and `facesWanted` (the menu's Analyzing sheet, the tool's
10	/// wait) are the switch's second and third readers: the `faces` kind through the analysis store
11	/// in forward-media source ticks (SW-84). Names no `rc_*`.
12	extension SpeakerSwitch {
13	
14	    // MARK: - The mode (SW-83)
15	
16	    /// Each speaker whose angle is the wide AND whose microphone another speaker shares is
17	    /// dropped; every other pairing comes back identical.
18	    static func withoutWide(_ pairing: Pairing) -> Pairing {
19	        guard let wide = pairing.wide else { return pairing }
20	        let speakers = pairing.speakers
21	        let kept = speakers.indices.filter { i in
22	            guard speakers[i].angle == wide, let mic = speakers[i].mic else { return true }
23	            return !speakers.indices.contains { $0 != i && speakers[$0].mic == mic }
24	        }
25	        return Pairing(speakers: kept.map { speakers[$0] }, wide: wide)
26	    }
27	
28	    /// The speakers with an angle that is not the wide, the first per angle.
29	    static func faceSpeakers(_ pairing: Pairing) -> [Speaker] {
30	        var seen: Set<UInt32> = []
31	        return pairing.speakers.filter { speaker in
32	            guard let angle = speaker.angle, angle != pairing.wide else { return false }
33	            return seen.insert(angle).inserted
34	        }
35	    }
36	
37	    /// Faces when two or more face speakers all name one microphone; else microphones.
38	    static func mode(_ pairing: Pairing) -> Mode {
39	        let speakers = faceSpeakers(pairing)
40	        guard speakers.count >= 2, let mic = speakers[0].mic,
41	            speakers.allSatisfy({ $0.mic == mic })
42	        else { return .microphones }
43	        return .faces
44	    }
45	
46	    /// The face speakers as their own labels — `(mic: angle, angle: angle)` — and the same wide,
47	    /// so `shots` maps `faceLabels`' `.person(angle)` to that angle.
48	    static func facePairing(_ pairing: Pairing) -> Pairing {
49	        Pairing(
50	            speakers: faceSpeakers(pairing).map { Speaker(mic: $0.angle, angle: $0.angle) },
51	            wide: pairing.wide)
52	    }
53	
54	    // MARK: - The labels (SW-81)
55	
56	    /// One label per step: `.person(angle track)`, `.crosstalk` or `.nobody`. A step is speech
57	    /// when the shared microphone covers it at v ≥ `voice_threshold`; the face speakers' angles
58	    /// contest it front first.
59	    static func faceLabels(_ input: Input) -> [Label] {
60	        let step = stepTicks
61	        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
62	        let nobody = [Label](repeating: .nobody, count: count)
63	        let speakers = faceSpeakers(input.pairing)
64	        guard let micTrack = speakers.first?.mic,
65	            let mic = input.microphones.first(where: { $0.track == micTrack }),
66	            mic.voice.count == count, mic.covered.count == count
67	        else { return nobody }
68	        let order = input.angles.map(\.track)
69	        let contest = speakers.compactMap(\.angle)
70	            .sorted { (order.firstIndex(of: $0) ?? .max) < (order.firstIndex(of: $1) ?? .max) }
71	        let series: [(UInt32, [Double?])] = contest.map { angle in
72	            let read = input.faces.first { $0.track == angle }?.activity ?? []
73	            return (angle, read.count == count ? read : [Double?](repeating: nil, count: count))
74	        }
75	        let threshold = input.settings.voiceThreshold
76	        return (0..<count).map { k in
77	            FaceActivity.label(
78	                speech: mic.covered[k] && mic.voice[k] >= threshold,
79	                activities: series.map { (angle: $0.0, activity: $0.1[k]) },
80	                ratio: input.settings.faceRatio, floor: input.settings.faceFloor)
81	        }
82	    }
83	
84	    /// An angle clip as the faces series reads it: its span, its times, its media's sample grid
85	    /// and duration, and the media's activity per grid index.
86	    struct FaceClip {
87	        let span: Span
88	        let times: AnalysisClipTimes
89	        let grid: AnalysisGrid
90	        let duration: Ticks
91	        let activity: [Double?]
92	    }
93	
94	    /// Step k's activity: the sample nearest the forward source tick of the step's midpoint,
95	    /// through the covering clip (the later-starting where two cover); nil off every clip or
96	    /// outside the media's 0…duration.
97	    static func faceSeries(_ clips: [FaceClip], from: Ticks, count: Int) -> [Double?] {
98	        let step = stepTicks
99	        return (0..<max(0, count)).map { k -> Double? in
100	            let mid = from + Ticks(k) * step + step / 2
101	            var covering: FaceClip?
102	            for clip in clips where clip.span.start <= mid && mid < clip.span.end {
103	                if covering.map({ clip.span.start >= $0.span.start }) ?? true { covering = clip }
104	            }
105	            guard let clip = covering else { return nil }
106	            let source = clip.times.source(atClip: mid - clip.span.start)
107	            guard source >= 0, source <= clip.duration else { return nil }
108	            let index = clip.grid.index(of: source)
109	            return index < clip.activity.count ? clip.activity[index] : nil
110	        }
111	    }
112	
113	    // MARK: - The store (SW-84)
114	
115	    /// A face speaker's angle clip of moving-video media crossing the range, and the window of
116	    /// its media the faces series needs: the part inside the range in source ticks, widened by
117	    /// half the activity window and clamped to 0…duration.
118	    struct FaceWindow {
119	        let track: UInt32
120	        let span: Span
121	        let media: MediaSnapshot
122	        let times: AnalysisClipTimes
123	        let window: ClosedRange<Ticks>
124	    }
125	
126	    static func faceWindows(
127	        in project: ReelProject, angles: [AngleTrack], pairing: Pairing, from: Ticks, to: Ticks
128	    ) -> [FaceWindow] {
129	        let snapshot = project.snapshot
130	        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
131	        let half = Ticks((FaceActivity.window / 2 * Double(ReelTime.perSecond)).rounded())
132	        var out: [FaceWindow] = []
133	        for angle in angles where wanted.contains(angle.track) {
134	            for span in angle.clips where span.end > from && span.start < to {
135	                guard let clip = snapshot.clip(span.clip), let media = snapshot.media(for: clip),
136	                    media.kind == .video, media.hasVideo
137	                else { continue }
138	                let times = AnalysisClipTimes(clip: clip, media: media, map: project.sourceMap(clip.id))
139	                let a = times.source(atClip: max(span.start, from) - span.start)
140	                let b = times.source(atClip: min(span.end, to) - span.start)
141	                let low = max(0, min(a, b) - half)
142	                let high = min(media.duration, max(a, b) + half)
143	                guard high > low else { continue }
144	                out.append(FaceWindow(
145	                    track: angle.track, span: span, media: media, times: times, window: low...high))
146	            }
147	        }
148	        return out
149	    }
150	
151	    /// The media's activity per grid index from the cached samples: each index the marker covers
152	    /// has the opening of its sample, the rest none.
153	    static func storedActivity(_ media: MediaSnapshot, grid: AnalysisGrid, cacheDir: URL)
154	        -> [Double?]
155	    {
156	        var openings = [Double?](repeating: nil, count: grid.count)
157	        if let marker = AnalysisStore.readMarker(.faces, media: media.id, in: cacheDir),
158	            let file = marker.files.first,
159	            let data = AnalysisStore.readPayload(.faces, media: media.id, file: file, in: cacheDir),
160	            let decoded = AnalysisFaces.decode(data), decoded.count == grid.count
161	        {
162	            for range in marker.ranges {
163	                for k in max(0, range.lowerBound)...min(grid.lastIndex, range.upperBound) {
164	                    openings[k] = FaceActivity.opening(decoded.samples[k])
165	                }
166	            }
167	        }
168	        let rate = grid.rate * Double(ReelTime.perSecond)
169	        return FaceActivity.activities(openings, half: FaceActivity.halfWidth(rate: rate))
170	    }
171	
172	    /// Each face speaker's angle, front first, on the range's grid, and the "still being
173	    /// analysed" problem for an angle any of whose windows the store does not answer (read as
174	    /// `[]`). Main thread.
175	    static func readFaces(
176	        from document: ProjectDocument, angles: [AngleTrack], pairing: Pairing, from: Ticks,
177	        count: Int
178	    ) -> (faces: [FaceAngle], problems: [String]) {
179	        let to = from + Ticks(max(0, count)) * stepTicks
180	        let windows = faceWindows(
181	            in: document.editedProject, angles: angles, pairing: pairing, from: from, to: to)
182	        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
183	        var activity: [UInt32: [Double?]] = [:]
184	        var faces: [FaceAngle] = []
185	        var problems: [String] = []
186	        for angle in angles where wanted.contains(angle.track) {
187	            var clips: [FaceClip] = []
188	            var pending = false
189	            for window in windows where window.track == angle.track {
190	                let missed: Bool
191	                do {
192	                    missed = try document.analysisRequest(
193	                        kind: .faces, media: window.media, window: window.window) != nil
194	                } catch {
195	                    missed = true
196	                }
197	                guard !missed, let cacheDir = document.cacheDirectory else {
198	                    pending = true
199	                    continue
200	                }
201	                let grid = AnalysisKind.faces.grid(of: window.media)
202	                let stored = activity[window.media.id]
203	                    ?? storedActivity(window.media, grid: grid, cacheDir: cacheDir)
204	                activity[window.media.id] = stored
205	                clips.append(FaceClip(
206	                    span: window.span, times: window.times, grid: grid,
207	                    duration: window.media.duration, activity: stored))
208	            }
209	            if pending {
210	                problems.append(
211	                    "The camera on track \(angle.track) is still being analysed — its faces have "
212	                        + "not been found yet. Try again in a moment.")
213	                faces.append(FaceAngle(track: angle.track, activity: []))
214	            } else {
215	                faces.append(FaceAngle(
216	                    track: angle.track, activity: faceSeries(clips, from: from, count: count)))
217	            }
218	        }
219	        return (faces, problems)
220	    }
221	
222	    /// One `faces` request a media still needs, and the first face-speaker angle clip needing it.
223	    struct FacesWant {
224	        let track: UInt32
225	        let clip: UInt32
226	        let media: MediaSnapshot
227	        let request: AnalysisRequest
228	    }
229	
230	    /// The requests the faces mode still needs, one per media in first-window order, each
231	    /// media's misses merged (`ShotSplit.wants`' shape); empty in the microphones mode or when
232	    /// every window is a hit. Main thread; throws `analysisRequest`'s errors.
233	    static func facesWanted(_ input: Input, in document: ProjectDocument) throws -> [FacesWant] {
234	        guard mode(input.pairing) == .faces else { return [] }
235	        let windows = faceWindows(
236	            in: document.editedProject, angles: input.angles, pairing: input.pairing,
237	            from: input.from, to: input.to)
238	        var order: [UInt32] = []
239	        var misses: [UInt32: [AnalysisRequest]] = [:]
240	        var first: [UInt32: FaceWindow] = [:]
241	        for window in windows {
242	            guard let request = try document.analysisRequest(
243	                kind: .faces, media: window.media, window: window.window)
244	            else { continue }
245	            let id = window.media.id
246	            if misses[id] == nil {
247	                order.append(id)
248	                first[id] = window
249	            }
250	            misses[id, default: []].append(request)
251	        }
252	        return order.compactMap { id in
253	            guard let requests = misses[id], let head = requests.first, let window = first[id]
254	            else { return nil }
255	            let request = AnalysisRequest(
256	                kind: head.kind, cacheDir: head.cacheDir, media: head.media, url: head.url,
257	                stamp: head.stamp, input: head.input,
258	                ranges: AnalysisStore.merged(requests.flatMap(\.ranges)))
259	            return FacesWant(
260	                track: window.track, clip: window.span.clip, media: window.media, request: request)
261	        }
262	    }
263	}
264	
265	extension AnalysisClipTimes {
266	    /// The forward source tick at `t` ticks from the clip's start: the inverse of
267	    /// `clipTime(ofSource:)` (its source map when it ramps, its speed when not, the reversed
268	    /// mirror last).
269	    func source(atClip t: Ticks) -> Int64 {
270	        let played: Int64
271	        if let map {
272	            played = Int64(map.source(atClip: Double(t)).rounded())
273	        } else {
274	            played = sourceIn + Int64((Double(t) * speed).rounded())
275	        }
276	        return pivot.map { ReverseMirror.mirrored(played, about: $0) } ?? played
277	    }
278	}
