28	    /// The sheet's opening values: each remembered key clamped into its range, an absent or
29	    /// unreadable key the default. Read through `double(forKey:)`, so a launch argument counts.
30	    static func remembered(_ d: UserDefaults) -> SpeakerSwitch.Settings {
31	        var s = SpeakerSwitch.Settings()
32	        func number(_ key: String, _ range: ClosedRange<Double>, _ fallback: Double) -> Double {
33	            guard d.object(forKey: key) != nil else { return fallback }
34	            let v = d.double(forKey: key)
35	            guard v.isFinite else { return fallback }
36	            return min(max(v, range.lowerBound), range.upperBound)
37	        }
38	        s.minShot = number(minShotKey, minShotRange, s.minShot)
39	        s.lead = number(leadKey, leadRange, s.lead)
40	        s.bleedDB = number(bleedKey, bleedRange, s.bleedDB)
41	        if let raw = d.string(forKey: crosstalkKey), let crosstalk = SpeakerSwitch.Crosstalk(rawValue: raw) {
42	            s.crosstalk = crosstalk
43	        }
44	        return s
45	    }
46	
47	    /// Writes only the remembered keys whose value differs from the sheet's opening values, so a
48	    /// sheet pressed as it opened moves no default (mcp.py's DEFAULTS MOVED guard).
49	    func remember(changedFrom opened: SpeakerSwitch.Settings, in d: UserDefaults) {
50	        if minShot != opened.minShot { d.set(minShot, forKey: Self.minShotKey) }
51	        if lead != opened.lead { d.set(lead, forKey: Self.leadKey) }
52	        if crosstalk != opened.crosstalk { d.set(crosstalk.rawValue, forKey: Self.crosstalkKey) }
53	        if bleedDB != opened.bleedDB { d.set(bleedDB, forKey: Self.bleedKey) }
54	    }
55	}
