3	/// What Switch by Speaker writes (spec §11 SW-23): the planned shots as one undo step "Switch by
4	/// Speaker" on a Program track — a new one directly in front of the front-most angle, or the
5	/// named track cleared over the range (Replace the shots on) — with the angles hidden, or their
6	/// pictures switched off, inside the range only. Clip ▸ Switch by Speaker…
7	/// (`SwitchSpeakerSheetController`) and `switch_by_speaker` (`AgentServer+Switch.swift`) both
8	/// write through `edit`.
9	///
10	/// Every op is tried ONE at a time on the container's handle through `SwitchAngle.Trial`
11	/// (`applying([ReelOp])` does not stop at a refusal), so the ids a later op names — the Program
12	/// track's, a split's second half — are the ones the commit will mint, and the first refusal
13	/// refuses the whole switch with nothing committed. Names no `rc_*`.
14	extension SpeakerSwitch {
15	    static let programName = "Program"
16	
17	    /// The ops, the Program track they write to, how many `copy_pieces` they hold, and the
18	    /// selection to set after them (SW-23 (f)).
19	    struct Edit {
20	        let ops: [ReelOp]
21	        let track: UInt32
22	        let copies: Int
23	        let selection: Set<UInt32>
24	    }
25	
26	    enum EditAnswer {
27	        case edit(Edit)
28	        case refused(String)
29	    }
30	
31	    /// SW-23 (g): two or more angles in SW-20's defaults, and a selected media clip whose sound
32	    /// is on and whose media has audio.
33	    static func canOffer(_ selection: [ClipSnapshot], in snapshot: ProjectSnapshot) -> Bool {
34	        guard defaults(selection: selection, in: snapshot).angles.count >= 2 else { return false }
35	        return selection.contains { clip in
36	            guard case .media = clip.source, clip.enabled.audio else { return false }
37	            return snapshot.media(for: clip)?.hasAudio == true
38	        }
39	    }
40	
41	    /// SW-23 (d): "Mute the cameras' own sound" is on by default when no microphone is an angle.
42	    static func muteDefault(_ input: Input) -> Bool {
43	        let angles = Set(input.angles.map(\.track))
44	        return !input.microphones.contains { angles.contains($0.track) }
45	    }
46	
47	    /// SW-23 (e): the tracks Replace the shots on may name, front first.
48	    static func replaceable(_ input: Input, selection: Set<UInt32>, in snapshot: ProjectSnapshot)
49	        -> [UInt32]
50	    {
51	        snapshot.tracks.reversed().map(\.id).filter {
52	            replaceRefusal($0, input: input, selection: selection, in: snapshot) == nil
53	        }
54	    }
55	
56	    /// The first of SW-23 (e)'s tests `track` fails, in its sentence; nil when it qualifies.
57	    static func replaceRefusal(
58	        _ track: UInt32, input: Input, selection: Set<UInt32>, in snapshot: ProjectSnapshot
59	    ) -> String? {
60	        let lead = "Track \(track) cannot take the shots: "
61	        guard let found = snapshot.track(track) else { return "no track with id \(track)" }
62	        if found.locked { return lead + "it is locked." }
63	        let clips = snapshot.clips(onTrack: track)
64	        if clips.contains(where: { selection.contains($0.id) }) {
65	            return lead + "it holds a selected clip."
66	        }
67	        guard let front = input.angles.first?.track,
68	            let frontIndex = snapshot.trackIndex(of: front),
69	            let index = snapshot.trackIndex(of: track), index > frontIndex
70	        else { return lead + "it is not in front of the angles." }
71	        let over = clips.filter { $0.end > input.from && $0.start < input.to }
72	        if over.isEmpty {
73	            let a = ReelTime.format(input.from, fps: input.fps, frames: true)
74	            let b = ReelTime.format(input.to, fps: input.fps, frames: true)
75	            return lead + "it has nothing between \(a) and \(b) to replace."
76	        }
77	        let played = Set(
78	            input.angles.flatMap(\.clips).compactMap { snapshot.clip($0.clip)?.source.mediaID })
79	        if let stranger = over.first(where: { clip in
80	            guard case .media = clip.source, let media = clip.source.mediaID else { return true }
81	            return !played.contains(media)
82	        }) {
83	            return lead + "clip \(stranger.id) is not a piece of an angle."
84	        }
85	        return nil
86	    }
87	
88	    /// SW-23's ops for `shots` (a `plan`'s, every shot's angle covering its span) over `input`'s
89	    /// range, tried on `container`, the handle of the container being edited. `replacing` is
90	    /// Replace's track, already through `replaceRefusal`. Throws only the core's invalid input.
91	    static func edit(
92	        _ shots: [Shot], input: Input, muteCameras: Bool, replacing: UInt32?,
93	        selection: Set<UInt32>, in container: ReelProject
94	    ) throws -> EditAnswer {
95	        let snapshot = container.snapshot
96	        let (from, to) = (input.from, input.to)
97	        let angles = input.angles.map(\.track)
98	        guard let front = angles.first, let frontIndex = snapshot.trackIndex(of: front) else {
99	            return .refused(
100	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
101	                    + "with a picture.")
102	        }
103	
104	        // (h): a linked angle clip crossing the range, before any op.
105	        for track in angles {
106	            for clip in SwitchAngle.pictureClips(on: track, in: snapshot)
107	            where clip.end > from && clip.start < to {
108	                if let partner = clip.linked {
109	                    return .refused(
110	                        "clip \(clip.id) on track \(track) is linked to clip \(partner) (Detach "
111	                            + "Audio's pair); Switch by Speaker cuts between cameras with no link "
112	                            + "— Attach Audio first")
113	                }
114	            }
115	        }
116	
117	        var trial = SwitchAngle.Trial(project: container)
118	        var chosen = selection
119	        func refusal(_ op: ReelOp) throws -> String? {
120	            try trial.require(op).map { "Switch by Speaker was refused at \(op.name): \($0)" }
121	        }
122	        /// Splits `clip` at `at`, a selected clip's new half joining the selection (f).
123	        func split(_ clip: ClipSnapshot, at: Ticks) throws -> String? {
124	            let known = Set(trial.project.snapshot.clips.map(\.id))
125	            if let why = try refusal(.split(clips: [clip.id], at: at)) { return why }
126	            if chosen.contains(clip.id) {
127	                chosen.formUnion(trial.project.snapshot.clips.map(\.id).filter { !known.contains($0) })
128	            }
129	            return nil
130	        }
131	        func inside(_ clip: ClipSnapshot) -> Bool { clip.start >= from && clip.end <= to }
132	
133	        // (a) The destination.
134	        let destination: UInt32
135	        if let replacing {
136	            for at in [from, to] {
137	                for clip in trial.project.snapshot.clips(onTrack: replacing)
138	                where clip.start < at && at < clip.end {
139	                    if let why = try split(clip, at: at) { return .refused(why) }
140	                }
141	            }
142	            let cleared = trial.project.snapshot.clips(onTrack: replacing).filter(inside).map(\.id)
143	            if !cleared.isEmpty, let why = try refusal(.delete(clips: cleared)) {
144	                return .refused(why)
145	            }
146	            destination = replacing
147	        } else {
148	            let before = Set(snapshot.tracks.map(\.id))
149	            let add = ReelOp.addTrack(index: frontIndex + 1, name: programName)
150	            if let why = try refusal(add) { return .refused(why) }
151	            guard let made = trial.project.snapshot.tracks.first(where: { !before.contains($0.id) })
152	            else { return .refused("Switch by Speaker was refused at add_track: no track was added.") }
153	            destination = made.id
154	        }
155	
156	        // (b) One copy_pieces per angle clip, in the order of its first range.
157	        var ranges: [UInt32: [(from: Ticks, to: Ticks)]] = [:]
158	        var order: [UInt32] = []
159	        for shot in shots {
160	            for piece in SwitchAngle.pieceRanges(
161	                angle: shot.angle, from: shot.start, to: shot.end, in: snapshot)
162	            {
163	                if ranges[piece.clip] == nil { order.append(piece.clip) }
164	                ranges[piece.clip, default: []].append((piece.from, piece.to))
165	            }
166	        }
167	        order.sort { (ranges[$0]?.first?.from ?? 0) < (ranges[$1]?.first?.from ?? 0) }
168	        for clip in order {
169	            let op = ReelOp.copyPieces(
170	                clip: clip, track: destination, ranges: ranges[clip] ?? [], video: true,
171	                audio: false)
172	            if let why = try refusal(op) { return .refused(why) }
173	        }
174	
175	        // (c), (d) The angles, front first.
176	        let microphones = Set(input.microphones.map(\.track))
177	        for track in angles {
178	            let mute = muteCameras && !microphones.contains(track)
179	            let now = trial.project.snapshot
180	            let pictures = SwitchAngle.pictureClips(on: track, in: now)
181	            let ids = Set(pictures.map(\.id))
182	            let all = now.clips(onTrack: track)
183	            if !all.isEmpty, all.allSatisfy({ ids.contains($0.id) && inside($0) }) {
184	                if now.track(track)?.hidden != true,
185	                    let why = try refusal(.setTrack(track: track, hidden: true))
186	                {
187	                    return .refused(why)
188	                }
189	                for clip in pictures where mute && clip.enabled.audio {
190	                    if let why = try refusal(.setEnabled(clip: clip.id, audio: false)) {
191	                        return .refused(why)
192	                    }
193	                }
194	                continue
195	            }
196	            for at in [from, to] {
197	                for clip in SwitchAngle.pictureClips(on: track, in: trial.project.snapshot)
198	                where clip.start < at && at < clip.end {
199	                    if let why = try split(clip, at: at) { return .refused(why) }
200	                }
201	            }
202	            for clip in SwitchAngle.pictureClips(on: track, in: trial.project.snapshot)
203	            where inside(clip) {
204	                let video: Bool? = clip.enabled.video ? false : nil
205	                let audio: Bool? = mute && clip.enabled.audio ? false : nil
206	                guard video != nil || audio != nil else { continue }
207	                if let why = try refusal(.setEnabled(clip: clip.id, video: video, audio: audio)) {
208	                    return .refused(why)
209	                }
210	            }
211	        }
212	        return .edit(
213	            Edit(ops: trial.ops, track: destination, copies: order.count, selection: chosen))
214	    }
215	}
