3	/// Who speaks when, as `reframe_clip {follow: speaker}` is handed it (road map
4	/// "creator-jobs" VR6a, spec §11 VR-60 (c)): SW-21's labels and SW-22 (a)–(e)
5	/// read exactly as `shots` reads them, but on the labels themselves, not on
6	/// angles, so the framing and Switch by Speaker agree about who is talking.
7	///
8	/// - the crosstalk bridge and the nobody bridge (`bridgedRuns`, SW-22 (a));
9	/// - a person run of at least `minTurn` starts that microphone's turn, a
10	///   crosstalk run of at least `crosstalkMin` one turn per microphone active
11	///   at any of its crosstalk steps; nobody and shorter runs hold;
12	/// - each start at `snap(onset − lead)`, never before the last start or the
13	///   range's start; the first start is the range's start;
14	/// - each turn ends at the next start, the last at the range's end, so the
15	///   turns tile the range (crosstalk turns share one span).
16	///
17	/// Pure (SW-25): reads no document, file or clock.
18	extension SpeakerSwitch {
19	    /// One microphone's turn: `mic` is its TRACK, `[from, to)` range ticks.
20	    struct Turn: Equatable {
21	        let mic: UInt32
22	        let from: Ticks
23	        let to: Ticks
24	    }
25	
26	    /// The turns of `input`'s read microphones over its range (this file's
27	    /// doc); empty when no run qualifies.
28	    static func turns(_ input: Input) -> [Turn] {
29	        let step = stepTicks
30	        guard step > 0, input.to > input.from else { return [] }
31	        let count = Int((input.to - input.from) / step)
32	        let microphones = input.microphones.filter { $0.level.count == count }
33	        let settings = input.settings
34	        func ticks(_ seconds: Double) -> Ticks {
35	            Ticks((seconds * Double(ReelTime.perSecond)).rounded())
36	        }
37	        let sets = activeSets(microphones, settings: settings)
38	        let steps = labels(microphones, settings: settings)
39	        let order = microphones.map(\.track)
40	
41	        var starts: [(mics: [UInt32], start: Ticks)] = []
42	        for run in bridgedRuns(steps, settings: settings) {
43	            let length = Ticks(run.end - run.start) * step
44	            var mics: [UInt32] = []
45	            switch run.label {
46	            case .nobody: break
47	            case .person(let mic):
48	                if length >= ticks(settings.minTurn) { mics = [mic] }
49	            case .crosstalk:
50	                guard length >= ticks(settings.crosstalkMin) else { break }
51	                var active = Set<UInt32>()
52	                for k in run.start..<min(run.end, sets.count) where sets[k].count >= 2 {
53	                    active.formUnion(sets[k])
54	                }
55	                mics = order.filter { active.contains($0) }
56	            }
57	            guard !mics.isEmpty, mics != starts.last?.mics else { continue }
58	            let at = max(
59	                starts.last?.start ?? input.from, input.from,
60	                ReelTime.snapToFrame(
61	                    input.from + Ticks(run.start) * step - ticks(settings.lead), fps: input.fps))
62	            if starts.last?.start == at {
63	                starts.removeLast()
64	                if starts.last?.mics == mics { continue }
65	            }
66	            starts.append((mics, at))
67	        }
68	        guard !starts.isEmpty else { return [] }
69	        starts[0].start = input.from
70	        var out: [Turn] = []
71	        for (index, start) in starts.enumerated() {
72	            let end = index + 1 < starts.count ? min(starts[index + 1].start, input.to) : input.to
73	            guard end > start.start else { continue }
74	            for mic in start.mics { out.append(Turn(mic: mic, from: start.start, to: end)) }
75	        }
76	        return out
77	    }
78	}
